+
+function streamed(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  return [...chunks.flatMap((c) => s.push(c)), ...s.end()];
+}
+
+function parsed(text: string): string[][] | typeof SyntaxError {
+  try {
+    return parseCsv(text);
+  } catch (e) {
+    if (e instanceof SyntaxError) return SyntaxError;
+    throw e;
+  }
+}
+
+function expectSameAsParseCsv(chunks: string[]) {
+  const want = parsed(chunks.join(""));
+  if (want === SyntaxError) expect(() => streamed(chunks)).toThrow(SyntaxError);
+  else expect(streamed(chunks)).toEqual(want);
+}
+
+test("a stream handles a row end, a doubled quote or a closing quote split across chunks", () => {
+  for (const text of ['a\r\nb', '"a""b"', '"a"\r\nb', '"a",b', "a\rb\r", '"a"\r', "\ufeffa", "\ufeff", "a\n", "a,", "\n\n", '"', 'a"']) {
+    for (let at = 0; at <= text.length; at++) expectSameAsParseCsv([text.slice(0, at), text.slice(at)]);
+    expectSameAsParseCsv([...text]);
+  }
+});
