+test("a stream drops a BOM only at the very start of the input", () => {
+  expect(streamed(["", "\ufeffa"])).toEqual([["a"]]);
+  expect(streamed(["a", "\ufeffb"])).toEqual([["a\ufeffb"]]);
+});
+
+test("a stream returns a row only once its whole row end has arrived", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb\r")).toEqual([["a"]]);
+  expect(s.push("c")).toEqual([]);
+  expect(s.end()).toEqual([["b\rc"]]);
+});
+
+test("a stream throws a SyntaxError for each input parseCsv rejects, and keeps throwing it", () => {
+  const s = new CsvStream();
+  expect(s.push('a\n"b"')).toEqual([["a"]]);
+  expect(() => s.push("c")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+  expect(() => streamed(['"a"', "\r"])).toThrow(SyntaxError);
+  expect(() => streamed(['"a"\r', "b"])).toThrow(SyntaxError);
+  expect(() => streamed(['"a', "b"])).toThrow(SyntaxError);
+});
+
+test("a stream agrees with parseCsv for random inputs split at random", () => {
+  let seed = 1;
+  const random = (n: number) => ((seed = (seed * 1103515245 + 12345) % 2147483648), seed % n);
+  const alphabet = ["a", "b", ",", '"', "\r", "\n", "\ufeff"];
+  for (let run = 0; run < 20000; run++) {
+    let text = "";
+    for (let k = random(12); k > 0; k--) text += alphabet[random(alphabet.length)];
+    const chunks: string[] = [];
+    for (let at = 0; at < text.length; ) {
