+
+const FIELD_START = 0;
+const UNQUOTED = 1;
+const UNQUOTED_CR = 2; // a `\r` in a field that is not quoted, waiting for the next character
+const QUOTED = 3;
+const QUOTE = 4; // a `"` in a quoted field, waiting for the next character
+const QUOTE_CR = 5; // a `\r` after a closing quote, which must be followed by `\n`
+
+/**
+ * Reads CSV as `parseCsv` does, from chunks of any size: `push` returns the rows whose row end has arrived, `end`
+ * returns the rest once the input is over. Together they return what `parseCsv` returns for the whole input, and
+ * they throw a SyntaxError where `parseCsv` would. Each call costs time in proportion to its chunk only.
+ */
+export class CsvStream {
+  #rows: string[][] = [];
+  #row: string[] = [];
+  #field = "";
+  #state = FIELD_START;
+  #offset = 0; // offset in the input of the chunk being read
+  #ended = false;
+  #error: unknown = undefined;
+
+  push(chunk: string): string[][] {
+    this.#check();
+    try {
+      this.#read(chunk);
+    } catch (e) {
+      throw (this.#error = e);
+    }
+    return this.#take();
+  }
+
+  end(): string[][] {
+    this.#check();
+    this.#ended = true;
+    switch (this.#state) {
+      case QUOTED:
+        throw (this.#error = new SyntaxError("a quoted field is still open at the end of the input"));
+      case QUOTE_CR:
+        throw (this.#error = new SyntaxError(`unexpected ${JSON.stringify("\r")} after a closing quote at offset ${this.#offset - 1}`));
+      case UNQUOTED_CR:
+        this.#field += "\r";
+      // falls through
+      default:
+        if (this.#state !== FIELD_START || this.#row.length > 0) this.#endRow();
+    }
+    return this.#take();
+  }
+
+  #check() {
+    if (this.#error !== undefined) throw this.#error;
+    if (this.#ended) throw new Error("the stream has already ended");
+  }
+
+  #read(chunk: string) {
+    const n = chunk.length;
+    let i = this.#offset === 0 && chunk.startsWith("\uFEFF") ? 1 : 0;
+    while (i < n) {
+      switch (this.#state) {
+        case FIELD_START:
+          if (chunk[i] === '"') {
+            i++;
+            this.#state = QUOTED;
+          } else this.#state = UNQUOTED;
+          break;
+        case UNQUOTED: {
+          let j = i;
+          while (j < n && chunk[j] !== "," && chunk[j] !== "\n" && chunk[j] !== "\r" && chunk[j] !== '"') j++;
+          this.#field += chunk.slice(i, j);
+          i = j;
+          if (j === n) break;
+          const c = chunk[i++];
+          if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.#offset + j}`);
+          if (c === ",") this.#endField();
+          else if (c === "\n") this.#endRow();
+          else this.#state = UNQUOTED_CR;
+          break;
+        }
+        case UNQUOTED_CR:
+          if (chunk[i] === "\n") {
+            i++;
+            this.#endRow();
+          } else {
+            this.#field += "\r";
+            this.#state = UNQUOTED;
+          }
+          break;
+        case QUOTED: {
+          const j = chunk.indexOf('"', i);
+          this.#field += chunk.slice(i, j < 0 ? n : j);
+          if (j < 0) i = n;
+          else {
+            i = j + 1;
+            this.#state = QUOTE;
+          }
+          break;
+        }
+        case QUOTE: {
+          const c = chunk[i];
+          if (c === '"') {
+            this.#field += '"';
+            this.#state = QUOTED;
+          } else if (c === ",") this.#endField();
+          else if (c === "\n") this.#endRow();
+          else if (c === "\r") this.#state = QUOTE_CR;
+          else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.#offset + i}`);
+          i++;
+          break;
+        }
+        case QUOTE_CR:
+          if (chunk[i] !== "\n") throw new SyntaxError(`unexpected ${JSON.stringify("\r")} after a closing quote at offset ${this.#offset + i - 1}`);
+          i++;
+          this.#endRow();
+          break;
+      }
+    }
+    this.#offset += n;
+  }
+
+  #endField() {
+    this.#row.push(this.#field);
+    this.#field = "";
+    this.#state = FIELD_START;
+  }
+
+  #endRow() {
+    this.#endField();
+    this.#rows.push(this.#row);
+    this.#row = [];
+  }
+
+  #take(): string[][] {
+    const rows = this.#rows;
+    this.#rows = [];
+    return rows;
+  }
+}

