+import { expect, test } from "bun:test";
+import { distinctInWindow } from "./window";
+
+function naive(events: { t: number; key: string }[], windowMs: number): number[] {
+  return events.map((e) => {
+    const keys = new Set<string>();
+    for (const other of events) if (other.t > e.t - windowMs && other.t <= e.t) keys.add(other.key);
+    return keys.size;
+  });
+}
+
+test("events in any order: later entries with earlier or equal times count", () => {
+  const events = [
+    { t: 20, key: "c" },
+    { t: 8, key: "a" },
+    { t: 0, key: "a" },
+    { t: 5, key: "b" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([1, 2, 1, 2]);
+});
+
+test("events at the same time all see each other", () => {
+  const events = [
+    { t: 3, key: "a" },
+    { t: 3, key: "b" },
+    { t: 3, key: "a" },
+  ];
+  expect(distinctInWindow(events, 1)).toEqual([2, 2, 2]);
+});
+
+test("the window excludes t - windowMs and includes t", () => {
+  const events = [
+    { t: 0, key: "a" },
+    { t: 10, key: "b" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([1, 1]);
+  expect(distinctInWindow(events, 10.5)).toEqual([1, 2]);
+});
+
+test("the bound is t - windowMs as computed in floating point", () => {
+  const events = [
+    { t: 0.2, key: "a" },
+    { t: 0.3, key: "b" },
+  ];
+  // 0.3 - 0.1 is 0.19999999999999998, so 0.2 is inside.
+  expect(distinctInWindow(events, 0.1)).toEqual([1, 2]);
+});
+
+test("a window too small to change t holds nothing, not even the event", () => {
+  const events = [
+    { t: 1e20, key: "a" },
+    { t: 1e20, key: "b" },
+    { t: 0, key: "c" },
+  ];
+  expect(distinctInWindow(events, 1)).toEqual([0, 0, 1]);
+});
+
+test("keys are compared exactly", () => {
